    "about.fact_temples_value": "23",
    "about.fact_area_label": "Diffusione storica",
    "about.fact_area_value": "Circa 6 kmq",
    "about.criteria_title": "Eccezionale valore universale",
    "about.criteria_i": "Criterio (i): Il tempio Kandariya e il pi\u00f9 ampio complesso di Khajuraho sono riconosciuti come capolavori in cui architettura e scultura si fondono in eccezionale armonia.",
    "about.criteria_iii": "Criterio (iii): i templi forniscono una testimonianza eccezionale della civilt\u00e0 Chandela attraverso templi, sculture e iscrizioni originali sopravvissuti ai cambiamenti storici.",
    "about.integrity_title": "Integrit\u00e0",
    "about.integrity_text": "La propriet\u00e0 comprende tutti gli elementi necessari per esprimere il suo significato: templi, sculture, iscrizioni e resti archeologici, con confini definiti e un'ubicazione controllata.",
    "about.authenticity_title": "Autenticit\u00e0",
    "about.authenticity_text": "Khajuraho conserva un'elevata autenticit\u00e0 nella forma, nel design, nei materiali, nell'artigianato e nell'ambientazione. Gli interventi successivi hanno mirato a preservare, e non ad alterare, il carattere originario.",
    "about.management_title": "Protezione e gestione",
    "about.management_text_1": "I monumenti sono protetti come patrimonio nazionale dalla legge indiana e gestiti dall'Archaeological Survey of India con il supporto amministrativo a livello distrettuale.",
    "about.management_text_2": "I piani di conservazione, la gestione dei visitatori e i controlli del turismo sono coordinati con le agenzie locali e statali per bilanciare la protezione e l\u2019accesso del pubblico.",
    "about.management_text_3": "Le priorit\u00e0 attuali includono la pressione del turismo, il cambiamento del contesto urbano e la gestione delle acque sotterranee nel pi\u00f9 ampio panorama archeologico.",
    "temples.component_locations_title": "Sedi dei componenti UNESCO",
    "temples.component_locations_desc": "Le mappe del Patrimonio Mondiale identificano le componenti protette nei gruppi occidentali, orientali e meridionali di Khajuraho. Le coordinate seguenti si basano sulla documentazione UNESCO.",
    "temples.component_locations_source": "Apri i dati della mappa UNESCO",
    "temples.component_group_western": "Gruppo occidentale",
    "temples.component_group_eastern": "Gruppo Orientale",
    "temples.component_group_southern": "Gruppo Meridionale",
    "temples.coordinates_label": "Coordinate",
    "privacy.title": "politica sulla riservatezza",
    "privacy.p1": "Questo sito Web memorizza solo le informazioni minime necessarie per elaborare il modulo di contatto e le richieste di abbonamento alla guida.",
    "privacy.p2": "I dettagli inviati vengono utilizzati solo per la risposta e l'assistenza ai visitatori. Non vendiamo informazioni personali.",
    "privacy.p3": "Per i documenti ufficiali del patrimonio, fare riferimento all'UNESCO e alle autorit\u00e0 competenti per il patrimonio indiano.",
    "terms.title": "Termini di servizio",
    "terms.p1": "I contenuti sono forniti a scopo educativo e di guida di viaggio sulla propriet\u00e0 di Khajuraho, Patrimonio dell'Umanit\u00e0.",
    "terms.p2": "Le informazioni storiche e sul patrimonio si basano su registri pubblici e documentazione UNESCO, ma non dovrebbero sostituire le note legali ufficiali.",
    "terms.p3": "Utilizzando questo sito Web, accetti di utilizzare le sue informazioni in modo responsabile e di verificare i dettagli critici del viaggio con fonti ufficiali.",
    "about.source_unesco_label": "Pagina dei beni UNESCO",
