    "about.p1": "\u0413\u0440\u0443\u043f\u043f\u0430 \u043f\u0430\u043c\u044f\u0442\u043d\u0438\u043a\u043e\u0432 \u041a\u0445\u0430\u0434\u0436\u0443\u0440\u0430\u0445\u043e \u0431\u044b\u043b\u0430 \u0432\u043d\u0435\u0441\u0435\u043d\u0430 \u0432 \u0421\u043f\u0438\u0441\u043e\u043a \u0432\u0441\u0435\u043c\u0438\u0440\u043d\u043e\u0433\u043e \u043d\u0430\u0441\u043b\u0435\u0434\u0438\u044f \u042e\u041d\u0415\u0421\u041a\u041e \u0432 1986 \u0433\u043e\u0434\u0443 \u0437\u0430 \u0441\u0432\u043e\u044e \u0438\u0441\u043a\u043b\u044e\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u0443\u044e \u0445\u0443\u0434\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u0443\u044e \u0438 \u0438\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u0446\u0435\u043d\u043d\u043e\u0441\u0442\u044c.",
    "about.p2": "\u042d\u0442\u0438 \u0445\u0440\u0430\u043c\u044b, \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0435 \u0434\u0438\u043d\u0430\u0441\u0442\u0438\u0435\u0439 \u0427\u0430\u043d\u0434\u0435\u043b\u0430 \u043c\u0435\u0436\u0434\u0443 950 \u0438 1050 \u0433\u043e\u0434\u0430\u043c\u0438 \u043d\u0430\u0448\u0435\u0439 \u044d\u0440\u044b, \u0441\u043e\u0447\u0435\u0442\u0430\u044e\u0442 \u0432 \u0441\u0435\u0431\u0435 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0443 \u0438 \u0441\u043a\u0443\u043b\u044c\u043f\u0442\u0443\u0440\u0443, \u0447\u0442\u043e\u0431\u044b \u0432\u044b\u0440\u0430\u0437\u0438\u0442\u044c \u0441\u0432\u044f\u0449\u0435\u043d\u043d\u044b\u0435 \u0437\u043d\u0430\u043d\u0438\u044f, \u0440\u0438\u0442\u0443\u0430\u043b\u044c\u043d\u0443\u044e \u0436\u0438\u0437\u043d\u044c \u0438 \u0447\u0435\u043b\u043e\u0432\u0435\u0447\u0435\u0441\u043a\u0438\u0439 \u043e\u043f\u044b\u0442.",
