    "about.criteria_i": "\u0627\u0644\u0645\u0639\u064a\u0627\u0631 (\u0637): \u064a\u0639\u062a\u0628\u0631 \u0645\u0639\u0628\u062f \u0643\u0627\u0646\u062f\u0627\u0631\u064a\u0627 \u0648\u0645\u062c\u0645\u0639 \u062e\u0627\u062c\u0648\u0631\u0627\u0647\u0648 \u0627\u0644\u0623\u0648\u0633\u0639 \u0645\u0646 \u0627\u0644\u062a\u062d\u0641 \u0627\u0644\u0641\u0646\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u0646\u062f\u0645\u062c \u0641\u064a\u0647\u0627 \u0627\u0644\u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0645\u0639\u0645\u0627\u0631\u064a\u0629 \u0648\u0627\u0644\u0646\u062d\u062a \u0641\u064a \u062a\u0646\u0627\u063a\u0645 \u0627\u0633\u062a\u062b\u0646\u0627\u0626\u064a.",
    "about.criteria_iii": "\u0627\u0644\u0645\u0639\u064a\u0627\u0631 (3): \u062a\u0642\u062f\u0645 \u0627\u0644\u0645\u0639\u0627\u0628\u062f \u0634\u0647\u0627\u062f\u0629 \u0628\u0627\u0631\u0632\u0629 \u0639\u0644\u0649 \u062d\u0636\u0627\u0631\u0629 \u0634\u0627\u0646\u062f\u064a\u0644\u0627 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0627\u0644\u0645\u0639\u0627\u0628\u062f \u0627\u0644\u0623\u0635\u0644\u064a\u0629 \u0648\u0627\u0644\u0645\u0646\u062d\u0648\u062a\u0627\u062a \u0648\u0627\u0644\u0646\u0642\u0648\u0634 \u0627\u0644\u062a\u064a \u0646\u062c\u062a \u0645\u0646 \u0627\u0644\u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u062a\u0627\u0631\u064a\u062e\u064a.",
    "about.integrity_title": "\u0646\u0632\u0627\u0647\u0629",
    "about.integrity_text": "\u062a\u0634\u062a\u0645\u0644 \u0627\u0644\u0645\u0644\u0643\u064a\u0629 \u0639\u0644\u0649 \u062c\u0645\u064a\u0639 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0636\u0631\u0648\u0631\u064a\u0629 \u0644\u0644\u062a\u0639\u0628\u064a\u0631 \u0639\u0646 \u0623\u0647\u0645\u064a\u062a\u0647\u0627: \u0627\u0644\u0645\u0639\u0627\u0628\u062f \u0648\u0627\u0644\u0645\u0646\u062d\u0648\u062a\u0627\u062a \u0648\u0627\u0644\u0646\u0642\u0648\u0634 \u0648\u0627\u0644\u0628\u0642\u0627\u064a\u0627 \u0627\u0644\u0623\u062b\u0631\u064a\u0629\u060c \u0645\u0639 \u062d\u062f\u0648\u062f \u0645\u062d\u062f\u062f\u0629 \u0648\u0645\u0648\u0642\u0639 \u0639\u0627\u0632\u0644 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u062d\u0643\u0645 \u0641\u064a\u0647.",
    "about.authenticity_title": "\u0623\u0635\u0627\u0644\u0629",
    "about.authenticity_text": "\u062a\u062d\u062a\u0641\u0638 \u062e\u0627\u062c\u0648\u0631\u0627\u0647\u0648 \u0628\u0627\u0644\u0623\u0635\u0627\u0644\u0629 \u0627\u0644\u0639\u0627\u0644\u064a\u0629 \u0641\u064a \u0627\u0644\u0634\u0643\u0644 \u0648\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u0644\u0645\u0648\u0627\u062f \u0648\u0627\u0644\u062d\u0631\u0641\u064a\u0629 \u0648\u0627\u0644\u0625\u0639\u062f\u0627\u062f. \u0647\u062f\u0641\u062a \u0627\u0644\u062a\u062f\u062e\u0644\u0627\u062a \u0627\u0644\u0644\u0627\u062d\u0642\u0629 \u0625\u0644\u0649 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0627\u0644\u0623\u0635\u0644\u064a\u0629 \u0648\u0644\u064a\u0633 \u062a\u063a\u064a\u064a\u0631\u0647\u0627.",
    "about.management_title": "\u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0648\u0627\u0644\u0625\u062f\u0627\u0631\u0629",
    "about.management_text_1": "\u0627\u0644\u0622\u062b\u0627\u0631 \u0645\u062d\u0645\u064a\u0629 \u0628\u0627\u0639\u062a\u0628\u0627\u0631\u0647\u0627 \u062a\u0631\u0627\u062b\u064b\u0627 \u0648\u0637\u0646\u064a\u064b\u0627 \u0628\u0645\u0648\u062c\u0628 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0647\u0646\u062f\u064a \u0648\u062a\u062f\u064a\u0631\u0647\u0627 \u0647\u064a\u0626\u0629 \u0627\u0644\u0645\u0633\u062d \u0627\u0644\u0623\u062b\u0631\u064a \u0641\u064a \u0627\u0644\u0647\u0646\u062f \u0628\u062f\u0639\u0645 \u0625\u062f\u0627\u0631\u064a \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0646\u0637\u0642\u0629.",
    "about.management_text_2": "\u064a\u062a\u0645 \u062a\u0646\u0633\u064a\u0642 \u062e\u0637\u0637 \u0627\u0644\u062d\u0641\u0638 \u0648\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0632\u0648\u0627\u0631 \u0648\u0636\u0648\u0627\u0628\u0637 \u0627\u0644\u0633\u064a\u0627\u062d\u0629 \u0645\u0639 \u0627\u0644\u0648\u0643\u0627\u0644\u0627\u062a \u0627\u0644\u0645\u062d\u0644\u064a\u0629 \u0648\u0627\u0644\u062d\u0643\u0648\u0645\u064a\u0629 \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062a\u0648\u0627\u0632\u0646 \u0628\u064a\u0646 \u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0648\u0627\u0644\u0648\u0635\u0648\u0644 \u0627\u0644\u0639\u0627\u0645.",
    "about.management_text_3": "\u0648\u062a\u0634\u0645\u0644 \u0627\u0644\u0623\u0648\u0644\u0648\u064a\u0627\u062a \u0627\u0644\u0645\u0633\u062a\u0645\u0631\u0629 \u0627\u0644\u0636\u063a\u0637 \u0645\u0646 \u0627\u0644\u0633\u064a\u0627\u062d\u0629\u060c \u0648\u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0633\u064a\u0627\u0642 \u0627\u0644\u062d\u0636\u0631\u064a\u060c \u0648\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u064a\u0627\u0647 \u0627\u0644\u062c\u0648\u0641\u064a\u0629 \u062d\u0648\u0644 \u0627\u0644\u0645\u0634\u0647\u062f \u0627\u0644\u0623\u062b\u0631\u064a \u0627\u0644\u0623\u0648\u0633\u0639.",
    "temples.component_locations_title": "\u0645\u0648\u0627\u0642\u0639 \u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u064a\u0648\u0646\u0633\u0643\u0648",
    "temples.component_locations_desc": "\u062a\u062d\u062f\u062f \u062e\u0631\u0627\u0626\u0637 \u0627\u0644\u062a\u0631\u0627\u062b \u0627\u0644\u0639\u0627\u0644\u0645\u064a \u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0645\u062d\u0645\u064a\u0629 \u0639\u0628\u0631 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0627\u062a \u0627\u0644\u063a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0634\u0631\u0642\u064a\u0629 \u0648\u0627\u0644\u062c\u0646\u0648\u0628\u064a\u0629 \u0645\u0646 \u062e\u0627\u062c\u0648\u0631\u0627\u0647\u0648. \u0627\u0644\u0625\u062d\u062f\u0627\u062b\u064a\u0627\u062a \u0623\u062f\u0646\u0627\u0647 \u0645\u0628\u0646\u064a\u0629 \u0639\u0644\u0649 \u0648\u062b\u0627\u0626\u0642 \u0627\u0644\u064a\u0648\u0646\u0633\u0643\u0648.",
