    "temples.component_group_western": "\u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629 \u0627\u0644\u063a\u0631\u0628\u064a\u0629",
    "temples.component_group_eastern": "\u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629 \u0627\u0644\u0634\u0631\u0642\u064a\u0629",
    "temples.component_group_southern": "\u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629 \u0627\u0644\u062c\u0646\u0648\u0628\u064a\u0629",
    "temples.coordinates_label": "\u0627\u0644\u0625\u062d\u062f\u0627\u062b\u064a\u0627\u062a",
    "privacy.title": "\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629",
    "privacy.p1": "\u064a\u0642\u0648\u0645 \u0645\u0648\u0642\u0639 \u0627\u0644\u0648\u064a\u0628 \u0647\u0630\u0627 \u0628\u062a\u062e\u0632\u064a\u0646 \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u062f\u0646\u0649 \u0641\u0642\u0637 \u0645\u0646 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0644\u0627\u0632\u0645\u0629 \u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0627\u0644\u062e\u0627\u0635 \u0628\u0643 \u0648\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643 \u0641\u064a \u0627\u0644\u062f\u0644\u064a\u0644.",
    "privacy.p2": "\u064a\u062a\u0645 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644 \u0627\u0644\u0645\u0642\u062f\u0645\u0629 \u0641\u0642\u0637 \u0644\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0648\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0632\u0648\u0627\u0631. \u0646\u062d\u0646 \u0644\u0627 \u0646\u0628\u064a\u0639 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0634\u062e\u0635\u064a\u0629.",
    "privacy.p3": "\u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0633\u062c\u0644\u0627\u062a \u0627\u0644\u062a\u0631\u0627\u062b \u0627\u0644\u0631\u0633\u0645\u064a\u0629\u060c \u064a\u0631\u062c\u0649 \u0627\u0644\u0631\u062c\u0648\u0639 \u0625\u0644\u0649 \u0627\u0644\u064a\u0648\u0646\u0633\u0643\u0648 \u0648\u0633\u0644\u0637\u0627\u062a \u0627\u0644\u062a\u0631\u0627\u062b \u0627\u0644\u0647\u0646\u062f\u064a\u0629 \u0630\u0627\u062a \u0627\u0644\u0635\u0644\u0629.",
    "terms.title": "\u0634\u0631\u0648\u0637 \u0627\u0644\u062e\u062f\u0645\u0629",
    "terms.p1": "\u064a\u062a\u0645 \u062a\u0648\u0641\u064a\u0631 \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0644\u0644\u0623\u063a\u0631\u0627\u0636 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0648\u062a\u0648\u062c\u064a\u0647\u0627\u062a \u0627\u0644\u0633\u0641\u0631 \u062d\u0648\u0644 \u0645\u0645\u062a\u0644\u0643\u0627\u062a \u0627\u0644\u062a\u0631\u0627\u062b \u0627\u0644\u0639\u0627\u0644\u0645\u064a \u0641\u064a \u062e\u0627\u062c\u0648\u0631\u0627\u0647\u0648.",
    "terms.p2": "\u062a\u0639\u062a\u0645\u062f \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u062a\u0627\u0631\u064a\u062e\u064a\u0629 \u0648\u0627\u0644\u062a\u0631\u0627\u062b\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u0633\u062c\u0644\u0627\u062a \u0627\u0644\u0639\u0627\u0645\u0629 \u0648\u0648\u062b\u0627\u0626\u0642 \u0627\u0644\u064a\u0648\u0646\u0633\u0643\u0648\u060c \u0648\u0644\u0643\u0646 \u0644\u0627 \u064a\u0646\u0628\u063a\u064a \u0623\u0646 \u062a\u062d\u0644 \u0645\u062d\u0644 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u0627\u0644\u0631\u0633\u0645\u064a\u0629.",
