    "visitor.entry_fee_title": "\u0ba8\u0bc1\u0bb4\u0bc8\u0bb5\u0bc1 \u0b95\u0b9f\u0bcd\u0b9f\u0ba3\u0bae\u0bcd",
    "visitor.entry_fee_line_1": "\u0b87\u0ba8\u0bcd\u0ba4\u0bbf\u0baf\u0bb0\u0bcd\u0b95\u0bb3\u0bc1\u0b95\u0bcd\u0b95\u0bc1 \u20b940",
