    "temples.component_name_5": "\u09ac\u09cd\u09b0\u09b9\u09cd\u09ae\u09be\u09b0 \u09ae\u09a8\u09cd\u09a6\u09bf\u09b0",
    "temples.component_name_6": "\u09b6\u09cd\u09b0\u09c0 \u09b9\u09a8\u09c1\u09ae\u09be\u09a8\u09c7\u09b0 \u09ac\u09bf\u09b6\u09be\u09b2 \u09ae\u09c2\u09b0\u09cd\u09a4\u09bf",
