    "about.p2": "950 \u0a85\u0aa8\u0ac7 1050 CE \u0aa8\u0ac0 \u0ab5\u0a9a\u0acd\u0a9a\u0ac7 \u0a9a\u0a82\u0aa6\u0ac7\u0ab2\u0abe \u0ab5\u0a82\u0ab6 \u0aa6\u0acd\u0ab5\u0abe\u0ab0\u0abe \u0aac\u0abe\u0a82\u0aa7\u0ab5\u0abe\u0aae\u0abe\u0a82 \u0a86\u0ab5\u0ac7\u0ab2, \u0a86 \u0aae\u0a82\u0aa6\u0abf\u0ab0\u0acb \u0aaa\u0ab5\u0abf\u0aa4\u0acd\u0ab0 \u0a9c\u0acd\u0a9e\u0abe\u0aa8, \u0aa7\u0abe\u0ab0\u0acd\u0aae\u0abf\u0a95 \u0a9c\u0ac0\u0ab5\u0aa8 \u0a85\u0aa8\u0ac7 \u0aae\u0abe\u0aa8\u0ab5 \u0a85\u0aa8\u0ac1\u0aad\u0ab5\u0aa8\u0ac7 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4 \u0a95\u0ab0\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0ab8\u0acd\u0aa5\u0abe\u0aaa\u0aa4\u0acd\u0aaf \u0a85\u0aa8\u0ac7 \u0ab6\u0abf\u0ab2\u0acd\u0aaa\u0aa8\u0ac7 \u0a9c\u0acb\u0aa1\u0ac7 \u0a9b\u0ac7.",
