    "contact.toast_desc": "\u0d0e\u0d24\u0d4d\u0d24\u0d3f\u0d2f\u0d24\u0d3f\u0d28\u0d4d \u0d28\u0d28\u0d4d\u0d26\u0d3f. \u0d1e\u0d19\u0d4d\u0d19\u0d7e \u0d09\u0d1f\u0d7b \u0d24\u0d28\u0d4d\u0d28\u0d46 \u0d28\u0d3f\u0d19\u0d4d\u0d19\u0d33\u0d46 \u0d2c\u0d28\u0d4d\u0d27\u0d2a\u0d4d\u0d2a\u0d46\u0d1f\u0d41\u0d02.",
