    "about.p3": "\u0632\u0646\u062f\u06c1 \u0628\u0686 \u062c\u0627\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0645\u0646\u062f\u0631\u0648\u06ba \u0645\u06cc\u06ba \u06c1\u0646\u062f\u0648 \u0627\u0648\u0631 \u062c\u06cc\u0646 \u06cc\u0627\u062f\u06af\u0627\u0631\u06cc\u06ba \u0634\u0627\u0645\u0644 \u06c1\u06cc\u06ba \u062c\u0648 \u0645\u063a\u0631\u0628\u06cc\u060c \u0645\u0634\u0631\u0642\u06cc \u0627\u0648\u0631 \u062c\u0646\u0648\u0628\u06cc \u062c\u06be\u0631\u0645\u0679 \u0645\u06cc\u06ba \u062a\u0631\u062a\u06cc\u0628 \u062f\u06cc \u06af\u0626\u06cc \u06c1\u06cc\u06ba\u060c \u062c\u0648 \u06c1\u0646\u062f\u0648\u0633\u062a\u0627\u0646 \u06a9\u06d2 \u0642\u0631\u0648\u0646 \u0648\u0633\u0637\u06cc \u06a9\u06d2 \u0645\u0646\u062f\u0631\u0648\u06ba \u06a9\u06d2 \u0633\u0628 \u0633\u06d2 \u0628\u06c1\u062a\u0631 \u0645\u0646\u0627\u0638\u0631 \u0645\u06cc\u06ba \u0633\u06d2 \u0627\u06cc\u06a9 \u06a9\u0648 \u0645\u062d\u0641\u0648\u0638 \u0631\u06a9\u06be\u062a\u06cc \u06c1\u06cc\u06ba\u06d4",
