    "temples.component_name_2": "\u0686\u0648\u0633\u0679\u06be \u062c\u0648\u06af\u06cc\u0646\u06cc \u0645\u0646\u062f\u0631",
    "temples.component_name_3": "\u0686\u0648\u067e\u0691\u0627 / \u0645\u0631\u0628\u0639 \u0679\u06cc\u0646\u06a9",
